static size_t operation_index(
	size_t initial_state, size_t sequence, size_t step,
	size_t count)
{
	size_t stride = 2U * (sequence % 8U) + 1U;

	return (initial_state + sequence + step * stride) % count;
}

static size_t condition_index(
	size_t initial_state, size_t sequence, size_t step,
	size_t multiplier, size_t count)
{
	return (initial_state * multiplier +
		sequence * (multiplier + 2U) +
		step * (multiplier + 4U)) % count;
}

size_t pqcp_runtime_transition_catalog_count(void)
{
	return ARRAY_SIZE(runtime_transition_fingerprints);
}

int pqcp_runtime_transition_catalog_get(
	size_t index,
	struct pqcp_runtime_transition_trace *trace)
{
	size_t initial_state;
	size_t sequence;

	if (index >= ARRAY_SIZE(runtime_transition_fingerprints) ||
	    trace == NULL) {
		return -EINVAL;
	}
	initial_state =
		index / TRANSITION_SEQUENCES_PER_STATE;
	sequence = index % TRANSITION_SEQUENCES_PER_STATE;
	memset(trace, 0, sizeof(*trace));
	trace->schema_version =
		PQCP_OPERATION_TRANSITION_SCHEMA_VERSION;
	trace->trace_id =
		PQCP_OPERATION_TRANSITION_TRACE_ID(
			PQCP_OPERATION_TRANSITION_RUNTIME,
			initial_state, sequence);
	trace->initial_state =
		(enum pqcp_runtime_policy_state)initial_state;
	trace->step_count =
		PQCP_OPERATION_TRANSITION_STEPS_PER_TRACE;
	for (size_t step = 0U;
	     step < trace->step_count; ++step) {
		trace->steps[step].command =
			(enum pqcp_runtime_command_kind)
				operation_index(
					initial_state, sequence, step,
					PQCP_RUNTIME_POLICY_COMMAND_COUNT);
		trace->steps[step].resource_condition =
			(enum pqcp_runtime_resource_condition)
				condition_index(
					initial_state, sequence, step, 3U,
					PQCP_RUNTIME_RESOURCE_CONDITION_COUNT);
		trace->steps[step].recovery_condition =
			(enum pqcp_runtime_recovery_condition)
				condition_index(
					initial_state, sequence, step, 5U,
					PQCP_RUNTIME_RECOVERY_CONDITION_COUNT);
	}
	trace->expected_fingerprint =
		runtime_transition_fingerprints[index];
	return 0;
}
